import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-06-29","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-06-29","date":"2020-06-29T00:00:00.000Z","updated":"2020-06-30T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-06-29.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-06-29.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-06-29.md"};function o(n,l,s,u,c,h){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2020年6月29日</li><li><strong>参会人员</strong>: [参会人员名单]</li><li><strong>主持人</strong>: [主持人姓名]</li></ul><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ol><li><p><strong>CI系统恢复</strong></p><ul><li>CI系统已恢复正常运行，这是一个积极的进展。</li></ul></li><li><p><strong>Alice替换问题</strong></p><ul><li>讨论了使用hominids属性创建OSD时的问题，特别是在测试Alice替换时。</li><li>决定明确要求用户将unmanned instructor参数设置为true，以防止集群中的STI重读。</li><li>需要进一步的信息来确定问题的具体情况，计划创建一个影响报告。</li></ul></li><li><p><strong>Rook拖拽组（drag groups）</strong></p><ul><li>讨论了Rook的节点亲和性和节点选择问题，决定采用社区的placement方法。</li><li>创建了一个相关的pull request（编号3552442），并计划与Blaine同步以获取更多关于高级Cuban a displacement规范的信息。</li></ul></li><li><p><strong>集成测试问题</strong></p><ul><li>讨论了集成测试中偶尔失败的问题，决定增加更多的日志信息以帮助诊断问题。</li></ul></li><li><p><strong>Rook客户端发现问题</strong></p><ul><li>Jeff Leighton创建了一个pull request，以从NSF组织切换到工作中的存储库，但由于不再支持在目录上部署OSD而导致失败。</li><li>需要移除对目录的支持，并更新Rook管理模块的schema检查。</li></ul></li><li><p><strong>升级测试</strong></p><ul><li>Yuri正在进行从Octopus到Pacific的升级测试，并已有一个pull request（编号35808）成功运行。</li><li>目前没有针对Pacific的升级测试，计划在未来进行。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>明确要求用户将unmanned instructor参数设置为true。</li><li>增加集成测试的日志信息以帮助诊断问题。</li><li>移除对目录的支持并更新Rook管理模块的schema检查。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>创建一个影响报告，收集更多关于Alice替换问题的信息。</li><li>与Blaine同步以获取更多关于高级Cuban a displacement规范的信息。</li><li>继续进行从Octopus到Pacific的升级测试，并计划未来进行Pacific的升级测试。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>本周工作进展较为缓慢，没有重大进展。</li><li>会议结束时，主持人提醒大家在下周继续同步工作进展。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在简短的讨论后结束，主持人祝愿大家周末愉快，并期待下周的同步。</li></ul>',13)])])}const _=e(r,[["render",o]]);export{d as __pageData,_ as default};
